// Golden flight trajectories for the C# / JS flight-model parity test (vehicles DESIGN §7).
//
// Runs scene3d/vehicle/flight_model.js (the predictor twin) over fixed quantized input sequences on an analytic
// ground and writes flight-golden.json: the inputs + the state every 30 steps. tests/vehicle_flight.test.mjs re-runs
// the JS model against it (exact); ACE.Server.Tests/Vehicles/FlightModelParityTests.cs runs the C# FlightModel and
// must agree within 1 mm after 30 s (900 steps).
//
//   node docs/vehicles-2026-11-01/flight/gen_golden.mjs          # regenerate
//   node docs/vehicles-2026-11-01/flight/gen_golden.mjs --check  # exit 1 if stale
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import * as FM from "../../../scene3d/vehicle/flight_model.js";
import { spreadOffsets, xorshift32 } from "../../../scene3d/vehicle/weapons.js";
import { stepFall } from "../../../scene3d/vehicle/fall_model.js";

const HERE = dirname(fileURLToPath(import.meta.url));
const OUT = join(HERE, "flight-golden.json");
const f32 = Math.fround;
const deg = (d) => f32((d * Math.PI) / 180);

// hellcat-demo (ACE Vehicles/VehicleProfile.cs HellcatDemo) as the f32 values the wire carries
export const PARAMS = {
  vMin: f32(30), vCruise: f32(83), vMax: f32(97), accel: f32(8), decel: f32(12),
  maxBank: deg(60), rollRate: deg(90), maxPitch: deg(25), pitchRate: deg(45), yawRate: deg(10),
  climbMax: f32(20), sinkMax: f32(25), floorAgl: f32(30), ceilingAgl: f32(450), takeoffClimb: f32(8), landingSpeed: f32(25),
};
export const GROUND = { kind: "analytic-v1", base: 40, amp: 25, kx: 173, ky: 131 };
export const ground = (x, y) => GROUND.base + GROUND.amp * Math.sin(x / GROUND.kx) * Math.cos(y / GROUND.ky);

function seq(spans) {
  // spans: [[count, throttle, pitch, roll, yaw, buttons], ...] → frames
  const frames = [];
  for (const [n, t, p, r, y, b] of spans) for (let i = 0; i < n; i++) frames.push([t, p, r, y, b]);
  return frames;
}

const X0 = 21700.5, Y0 = 3190.25; // around Holtburg (lb 0x71 0x10 region in world metres; any value works)
const SEQUENCES = [
  {
    name: "takeoff-climb-turns",
    initial: { x: X0, y: Y0, z: ground(X0, Y0), heading: 0.5, pitch: 0, bank: 0, speed: 0, mode: FM.MODE.PARKED },
    frames: seq([
      [30, 0, 0, 0, 0, 0], [170, 255, 0, 0, 0, 0], [90, 255, 0, 127, 0, 0], [90, 255, 0, 0, 0, 0],
      [90, 200, 0, -127, 0, 0], [60, 200, 127, 0, 0, 0], [60, 200, -127, 0, 0, 0], [60, 255, 0, 40, 0, 1],
      [60, 128, 0, 0, 127, 0], [190, 128, 30, -60, -20, 0],
    ]),
  },
  {
    name: "land",
    initial: { x: X0 + 400, y: Y0 - 300, z: ground(X0 + 400, Y0 - 300) + 60, heading: 2.0, pitch: 0, bank: 0, speed: 69, mode: FM.MODE.FLIGHT },
    frames: seq([[100, 64, 0, 20, 0, 0], [800, 64, 0, 0, 10, 4]]),
  },
  {
    name: "derelict-crash",
    initial: { x: X0 - 500, y: Y0 + 250, z: ground(X0 - 500, Y0 + 250) + 100, heading: 4.0, pitch: 0, bank: 0.3, speed: 60, mode: FM.MODE.DERELICT },
    frames: seq([[900, 0, -64, 0, 0, 0]]),
  },
  {
    name: "envelope-floor-ceiling",
    initial: { x: X0 + 900, y: Y0 + 900, z: ground(X0 + 900, Y0 + 900) + 30, heading: 5.5, pitch: 0, bank: 0, speed: 50, mode: FM.MODE.FLIGHT },
    frames: seq([[200, 255, -127, 10, 0, 0], [500, 255, 127, -10, 0, 1], [200, 100, 0, 127, 127, 0]]),
  },
  {
    name: "slow-small-bank",
    initial: { x: X0 - 900, y: Y0 - 900, z: ground(X0 - 900, Y0 - 900) + 120, heading: 6.1, pitch: 0, bank: 0, speed: 40, mode: FM.MODE.FLIGHT },
    frames: seq([[900, 30, 1, 1, -1, 0]]),
  },
];

const VCAP = f32(69);

export function run(s) {
  const st = { ...s.initial };
  const checkpoints = [];
  s.frames.forEach(([throttle, pitch, roll, yaw, buttons], i) => {
    FM.step(st, FM.inputFromFrame({ throttle, pitch, roll, yaw, buttons }), PARAMS, VCAP, ground, FM.DT);
    if ((i + 1) % 30 === 0) checkpoints.push({ step: i + 1, state: { ...st } });
  });
  return checkpoints;
}

const doc = {
  spec: "vehicles flight golden v1 — generated by gen_golden.mjs from scene3d/vehicle/flight_model.js; do not edit",
  dt: FM.DT,
  vCap: VCAP,
  params: PARAMS,
  ground: GROUND,
  sequences: SEQUENCES.map((s) => ({ name: s.name, initial: s.initial, frames: s.frames, checkpoints: run(s) })),
  // bail-out fall (ACE VehicleBailout.StepFall ↔ fall_model.js): 25 s free fall then the chute, from 450 m
  fall: (() => {
    const f = { x: 21000.25, y: 3300.5, z: 520.0, vx: 60.0, vy: -20.0, vz: 3.0, heading: 1.2, chute: false };
    const initial = { ...f };
    const checkpoints = [];
    for (let i = 1; i <= 1500; i++) {
      if (i === 300) f.chute = true;
      stepFall(f, FM.DT);
      if (i % 50 === 0) checkpoints.push({ step: i, state: { ...f } });
    }
    return { initial, chuteAtStep: 300, steps: 1500, checkpoints };
  })(),
  // gun spread replay (ACE VehicleWeapons.SpreadOffset ↔ weapons.js spreadOffsets)
  spread: {
    seed: 0x9e3779b9,
    spread: deg(1.5),
    offsets: spreadOffsets(0x9e3779b9, 8, deg(1.5)),
    xorshift: [0x9e3779b9, 1, 0xdeadbeef].map((v) => [v, xorshift32(v)]),
  },
};
const text = JSON.stringify(doc) + "\n";
if (process.argv.includes("--check")) {
  if (!existsSync(OUT) || readFileSync(OUT, "utf8") !== text) {
    console.error("flight-golden.json is STALE — run gen_golden.mjs");
    process.exit(1);
  }
  console.log("flight golden up to date");
} else {
  writeFileSync(OUT, text);
  for (const s of doc.sequences) {
    const last = s.checkpoints[s.checkpoints.length - 1].state;
    console.log(`${s.name.padEnd(24)} final mode=${FM.MODE_NAMES[last.mode]} speed=${last.speed.toFixed(2)} pos=(${last.x.toFixed(2)}, ${last.y.toFixed(2)}, ${last.z.toFixed(2)})`);
  }
  console.log(`wrote ${OUT}`);
}
